function g25Ref(rc){const e=BUILTIN_RAIN.find(x=>x.id==="g25-"+rc);if(!e)return null;const r=JSON.parse(JSON.stringify(e.rain));return {type:"table",region:r.region,code:rc,src:r.src,durs:r.durs,tbl:r.tbl};}
function genFit(d,H){ // 1~H시간 강우강도에 I = a/(tⁿ+b) (t: 분)를 ln 오차 최소로 맞춤
  H=Math.min(H||24,d.length);const t=[],y=[];for(let h=1;h<=H;h++){t.push(h*60);y.push(Math.log(d[h-1]/h));}
  const err=(n,b)=>{const z=t.map((x,i)=>y[i]+Math.log(Math.pow(x,n)+b));const la=z.reduce((p,q)=>p+q,0)/z.length;let s=0;z.forEach(v=>s+=(v-la)**2);return [s,Math.exp(la)];};
  let best=[1e99];for(let n=0.30;n<=1.20;n+=0.02)for(const b of [0,2,5,10,20,40,70,120,200]){const [e]=err(n,b);if(e<best[0])best=[e,n,b];}
  let [e,n,b]=best,sn=0.02,sb=Math.max(1,b*0.5);
  for(let k=0;k<80;k++){let imp=false;for(const [dn,db] of [[sn,0],[-sn,0],[0,sb],[0,-sb]]){const nn=n+dn,bb=Math.max(0,b+db);const [ee]=err(nn,bb);if(ee<e){e=ee;n=nn;b=bb;imp=true;}}if(!imp){sn/=2;sb/=2;}}
  const a=err(n,b)[1];return {a:+a.toPrecision(6),b:+b.toPrecision(5),n:+n.toPrecision(5)};
}
const WGEN_H=24;
function wamisGen(k){k.gen=k.tbl.map(r=>({T:r.T,...genFit(r.d,WGEN_H)}));k.genFit=WGEN_H;return k;}
function wamisRain(code,sub,refCode){
  const s=wStInfo(code);if(!s)return null;
  const rows=WAMIS_D[String(s[0])].split(";").map(r=>{let a=0;return r.split(",").map(v=>(a+=+v)/10);});
  return wamisGen({type:"wamis",region:s[1],code:s[0],basin:s[2],agency:s[3],src:`${WAMIS_SRC} 지점 ${s[0]}`,sub:sub||"ratio",
    tbl:WAMIS_T.map((T,i)=>({T,d:rows[i]})),ref:g25Ref(refCode||s[4])});
}
